mapper.select:
SELECT g.id, g.selection_id, g.student_id, g.course_id, g.semester_id, g.usual_score, g.exam_score, g.total_score, g.grade_point, g.is_pass, g.status, g.input_by, g.input_time, g.publish_time, g.remark, g.create_time, g.update_time, su.real_name AS studentName, st.stu_no AS stuNo, st.class_name AS className, c.course_code AS courseCode, c.course_name AS courseName, c.credit AS credit, se.semester_name AS semesterName FROM course_grade g
WHERE g.deleted = 0
AND g.student_id = #{studentId}
AND g.course_id = #{courseId}
AND g.semester_id = #{semesterId}
AND g.status = #{status}
ORDER BY st.stu_no ASC, g.id ASC

SELECT g.id, g.selection_id, g.student_id, g.course_id, g.semester_id, g.usual_score, g.exam_score, g.total_score, g.grade_point, g.is_pass, g.status, g.remark, g.create_time, g.update_time, c.course_code AS courseCode, c.course_name AS courseName, c.credit AS credit, se.semester_name AS semesterName FROM course_grade g INNER JOIN course c ON c.id = g.course_id AND c.deleted = 0 LEFT JOIN semester se ON se.id = g.semester_id AND se.deleted = 0 WHERE g.deleted = 0 AND g.student_id = #{studentId}
AND g.semester_id = #{semesterId}
AND g.status = 1
ORDER BY g.semester_id DESC, c.course_code ASC

SELECT g.course_id AS id, ROUND(AVG(g.total_score), 1) AS avgScore FROM course_grade g WHERE g.deleted = 0 AND g.status = 1 AND g.total_score IS NOT NULL AND g.course_id IN
#{id}
GROUP BY g.course_id
